create or replace function private.can_view_classroom(p_classroom uuid,p_user uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.educator_classrooms c where c.id=p_classroom and c.educator_id=p_user)
 or exists(select 1 from public.educator_classroom_members m where m.classroom_id=p_classroom and m.learner_id=p_user and m.status='active')
 or exists(select 1 from public.profiles p where p.id=p_user and p.role='admin');
$$;
revoke all on function private.can_view_classroom(uuid,uuid) from public,anon,authenticated;

drop policy if exists educator_classrooms_visible on public.educator_classrooms;
create policy educator_classrooms_visible on public.educator_classrooms for select to authenticated using (private.can_view_classroom(id,(select auth.uid())));
drop policy if exists educator_members_visible on public.educator_classroom_members;
create policy educator_members_visible on public.educator_classroom_members for select to authenticated using (learner_id=(select auth.uid()) or private.is_admin_user() or exists(select 1 from public.educator_classrooms c where c.id=classroom_id and c.educator_id=(select auth.uid())));

create or replace function private.protect_educator_verification_fields() returns trigger language plpgsql set search_path='' as $$
begin
 if (select auth.uid())=old.user_id and not private.is_admin_user() then new.verified:=old.verified;new.verified_by:=old.verified_by;new.verified_at:=old.verified_at;new.partner_organization_id:=old.partner_organization_id;end if;return new;
end;$$;
revoke all on function private.protect_educator_verification_fields() from public,anon,authenticated;
drop trigger if exists trg_protect_educator_verification_fields on public.educator_profiles;
create trigger trg_protect_educator_verification_fields before update on public.educator_profiles for each row execute function private.protect_educator_verification_fields();

create or replace function private.activate_my_educator_profile(p_partner_org_id uuid,p_role_title text,p_subject_areas text[],p_stage_keys text[])
returns public.educator_profiles language plpgsql security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_org public.sector_partner_organizations%rowtype;v_row public.educator_profiles%rowtype;
begin if v_uid is null then raise exception 'authentication required';end if;select * into v_org from public.sector_partner_organizations where id=p_partner_org_id and verification_status='verified';if not found or v_org.partner_type_key not in ('school','college_tvet','university','training_mentor') then raise exception 'verified education or training partner required';end if;if not private.has_sector_partner_membership(v_org.id,v_uid,false) then raise exception 'active partner membership required';end if;insert into public.educator_profiles(user_id,partner_organization_id,role_title,subject_areas,stage_keys,verified,verified_by,verified_at,active,updated_at) values(v_uid,v_org.id,coalesce(nullif(trim(p_role_title),''),'Educator'),coalesce(p_subject_areas,'{}'),coalesce(p_stage_keys,'{}'),true,v_org.verified_by,coalesce(v_org.verified_at,now()),true,now()) on conflict(user_id) do update set partner_organization_id=excluded.partner_organization_id,role_title=excluded.role_title,subject_areas=excluded.subject_areas,stage_keys=excluded.stage_keys,verified=true,verified_by=excluded.verified_by,verified_at=excluded.verified_at,active=true,updated_at=now() returning * into v_row;return v_row;end;$$;
revoke all on function private.activate_my_educator_profile(uuid,text,text[],text[]) from public,anon,authenticated;
create or replace function public.activate_my_educator_profile(p_partner_org_id uuid,p_role_title text default 'Educator',p_subject_areas text[] default '{}',p_stage_keys text[] default '{}') returns public.educator_profiles language sql set search_path='' as $$select * from private.activate_my_educator_profile(p_partner_org_id,p_role_title,p_subject_areas,p_stage_keys);$$;
revoke all on function public.activate_my_educator_profile(uuid,text,text[],text[]) from public,anon;grant execute on function public.activate_my_educator_profile(uuid,text,text[],text[]) to authenticated,service_role;

create or replace function private.create_my_classroom(p_title text,p_stage_key text,p_subject text default null)
returns public.educator_classrooms language plpgsql security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_ep public.educator_profiles%rowtype;v_row public.educator_classrooms%rowtype;
begin if v_uid is null then raise exception 'authentication required';end if;select * into v_ep from public.educator_profiles where user_id=v_uid and verified and active;if not found then raise exception 'verified educator profile required';end if;if not exists(select 1 from public.education_audience_stages where stage_key=p_stage_key) then raise exception 'invalid education stage';end if;if nullif(trim(p_title),'') is null then raise exception 'classroom title required';end if;insert into public.educator_classrooms(educator_id,partner_organization_id,title,stage_key,subject) values(v_uid,v_ep.partner_organization_id,trim(p_title),p_stage_key,nullif(trim(coalesce(p_subject,'')),'')) returning * into v_row;return v_row;end;$$;
revoke all on function private.create_my_classroom(text,text,text) from public,anon,authenticated;
create or replace function public.create_my_classroom(p_title text,p_stage_key text,p_subject text default null) returns public.educator_classrooms language sql set search_path='' as $$select * from private.create_my_classroom(p_title,p_stage_key,p_subject);$$;
revoke all on function public.create_my_classroom(text,text,text) from public,anon;grant execute on function public.create_my_classroom(text,text,text) to authenticated,service_role;

create or replace function private.join_educator_classroom(p_join_code text)
returns public.educator_classroom_members language plpgsql security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_c public.educator_classrooms%rowtype;v_stage text;v_row public.educator_classroom_members%rowtype;
begin if v_uid is null then raise exception 'authentication required';end if;select education_stage_key into v_stage from public.profiles where id=v_uid and role='student';if v_stage is null then raise exception 'learner education stage required';end if;select * into v_c from public.educator_classrooms where upper(join_code)=upper(trim(p_join_code)) and active;if not found then raise exception 'active classroom not found';end if;if v_c.stage_key<>v_stage then raise exception 'classroom is for a different education stage';end if;insert into public.educator_classroom_members(classroom_id,learner_id,status) values(v_c.id,v_uid,'active') on conflict(classroom_id,learner_id) do update set status='active',joined_at=now() returning * into v_row;return v_row;end;$$;
revoke all on function private.join_educator_classroom(text) from public,anon,authenticated;
create or replace function public.join_educator_classroom(p_join_code text) returns public.educator_classroom_members language sql set search_path='' as $$select * from private.join_educator_classroom(p_join_code);$$;
revoke all on function public.join_educator_classroom(text) from public,anon;grant execute on function public.join_educator_classroom(text) to authenticated,service_role;

create or replace function private.record_educator_observation(p_classroom_id uuid,p_learner_id uuid,p_competency_id uuid,p_score numeric,p_notes text,p_observation_type text default 'mastery_observation')
returns public.educator_observations language plpgsql security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid());v_row public.educator_observations%rowtype;
begin if v_uid is null then raise exception 'authentication required';end if;if not exists(select 1 from public.educator_profiles where user_id=v_uid and verified and active) then raise exception 'verified educator required';end if;if not exists(select 1 from public.educator_classrooms c join public.educator_classroom_members m on m.classroom_id=c.id and m.status='active' where c.id=p_classroom_id and c.educator_id=v_uid and m.learner_id=p_learner_id) then raise exception 'learner is not active in your classroom';end if;if p_competency_id is not null and not exists(select 1 from public.learning_competencies lc join public.profiles p on p.id=p_learner_id where lc.id=p_competency_id and lc.stage_key=p.education_stage_key) then raise exception 'competency does not match learner education stage';end if;if p_score is not null and (p_score<0 or p_score>100) then raise exception 'score must be 0 to 100';end if;if nullif(trim(p_notes),'') is null then raise exception 'observation notes required';end if;insert into public.educator_observations(classroom_id,educator_id,learner_id,competency_id,observation_type,score,notes) values(p_classroom_id,v_uid,p_learner_id,p_competency_id,p_observation_type,p_score,trim(p_notes)) returning * into v_row;return v_row;end;$$;
revoke all on function private.record_educator_observation(uuid,uuid,uuid,numeric,text,text) from public,anon,authenticated;
create or replace function public.record_educator_observation(p_classroom_id uuid,p_learner_id uuid,p_competency_id uuid,p_score numeric,p_notes text,p_observation_type text default 'mastery_observation') returns public.educator_observations language sql set search_path='' as $$select * from private.record_educator_observation(p_classroom_id,p_learner_id,p_competency_id,p_score,p_notes,p_observation_type);$$;
revoke all on function public.record_educator_observation(uuid,uuid,uuid,numeric,text,text) from public,anon;grant execute on function public.record_educator_observation(uuid,uuid,uuid,numeric,text,text) to authenticated,service_role;

create or replace function public.get_my_teacher_dashboard() returns jsonb language sql stable security invoker set search_path='' as $$with me as(select * from public.educator_profiles where user_id=(select auth.uid()) and verified and active),cs as(select * from public.educator_classrooms where educator_id=(select auth.uid()) and active),members as(select m.* from public.educator_classroom_members m join cs on cs.id=m.classroom_id where m.status='active'),gaps as(select lc.domain_title,round(avg(coalesce(mr.mastery_score,0)),2) avg_score,count(*) competency_rows from members mm join public.profiles p on p.id=mm.learner_id join public.learning_competencies lc on lc.stage_key=p.education_stage_key left join public.learner_mastery_records mr on mr.user_id=mm.learner_id and mr.competency_id=lc.id group by lc.domain_title) select jsonb_build_object('educator',(select to_jsonb(me) from me),'classrooms',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'stage_key',c.stage_key,'subject',c.subject,'join_code',c.join_code,'learner_count',(select count(*) from members m where m.classroom_id=c.id)) order by c.created_at desc) from cs c),'[]'::jsonb),'learner_count',(select count(*) from members),'mastery_gaps',coalesce((select jsonb_agg(to_jsonb(g) order by g.avg_score asc) from gaps g),'[]'::jsonb),'recent_observations',coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at desc) from (select * from public.educator_observations where educator_id=(select auth.uid()) order by created_at desc limit 12)o),'[]'::jsonb));$$;
revoke all on function public.get_my_teacher_dashboard() from public,anon;grant execute on function public.get_my_teacher_dashboard() to authenticated,service_role;

create or replace function public.get_my_classroom_detail(p_classroom_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$select jsonb_build_object('classroom',(select to_jsonb(c) from public.educator_classrooms c where c.id=p_classroom_id and private.can_view_classroom(c.id,(select auth.uid()))),'learners',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'full_name',p.full_name,'stage_key',p.education_stage_key,'grade_level',p.grade_level,'institution_name',p.institution_name,'mastery',(select jsonb_build_object('overall_score',round(avg(mr.mastery_score),2),'evidence_count',coalesce(sum(mr.evidence_count),0)) from public.learner_mastery_records mr where mr.user_id=p.id)) order by p.full_name) from public.educator_classroom_members m join public.profiles p on p.id=m.learner_id where m.classroom_id=p_classroom_id and m.status='active'),'[]'::jsonb));$$;
revoke all on function public.get_my_classroom_detail(uuid) from public,anon;grant execute on function public.get_my_classroom_detail(uuid) to authenticated,service_role;

